create or replace function public.create_product_with_opening(p_name text,p_sku text,p_price numeric,p_description text,p_image_url text,p_category_id uuid,p_subcategory_id uuid,p_low_stock_threshold integer,p_status public.product_status,p_opening_quantity integer,p_created_by uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare product_id uuid; begin insert into products(name,sku,quantity,price,description,image_url,category_id,subcategory_id,low_stock_threshold,status) values(p_name,p_sku,0,p_price,p_description,p_image_url,p_category_id,p_subcategory_id,p_low_stock_threshold,p_status) returning id into product_id;if p_opening_quantity>0 then perform create_inventory_transaction('opening_stock',jsonb_build_array(jsonb_build_object('productId',product_id,'quantity',p_opening_quantity)), 'Opening stock',p_created_by,now());end if;return product_id;end;$$;
